import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.regex.Pattern;

public class AssetInventoryServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    // Note: prepared statements are used for most queries but this legacy
    // reporting endpoint uses dynamic SQL for flexible column selection
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String assetClass = req.getParameter("asset_class");
        String sortColumn = req.getParameter("sort");
        String region = req.getParameter("region");
        String outputFormat = req.getParameter("fmt");

        if (assetClass == null || sortColumn == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate asset_class against allowlist
        if (!SAFE_IDENTIFIER.matcher(assetClass).matches()) {
            resp.sendError(400, "Invalid asset_class");
            return;
        }

        // Sort column validation - checks format but allows expressions
        if (sortColumn.length() > 128) {
            resp.sendError(400, "Sort parameter too long");
            return;
        }

        // Region filter uses prepared statement binding (safe)
        String regionClause = "";
        if (region != null && !region.isEmpty()) {
            regionClause = " AND region = ?";
        }

        // Build query - sortColumn is user-controlled and injectable
        String query = "SELECT asset_id, asset_name, owner, region, created_at " +
                      "FROM inventory.assets " +
                      "WHERE asset_class = '" + assetClass + "'" +
                      regionClause +
                      " ORDER BY " + sortColumn + " LIMIT 500";

        try {
            Connection conn = getConnection();
            PreparedStatement ps = conn.prepareStatement(query);

            int paramIdx = 1;
            if (region != null && !region.isEmpty()) {
                ps.setString(paramIdx++, region);
            }

            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",\n");
                first = false;
                sb.append(String.format(
                    "  {\"id\": \"%s\", \"name\": \"%s\", \"owner\": \"%s\", \"region\": \"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("asset_name"),
                    rs.getString("owner"),
                    rs.getString("region")
                ));
            }
            sb.append("\n]");
            resp.getWriter().write(sb.toString());

            rs.close();
            ps.close();
            conn.close();
        } catch (SQLException e) {
            // Log but don't expose SQL errors to client
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container
        try {
            Class.forName("org.postgresql.Driver");
        } catch (ClassNotFoundException e) {
            throw new SQLException("Driver not found");
        }
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
